```swift
import UIKit

class DayViewCalendarController: UIViewController, UICollectionViewDelegate {
    private var collectionView: UICollectionView!
    private var dataSource: UICollectionViewDiffableDataSource<Int, Date>!
    private var currentDay: Date = Date()

    override func viewDidLoad() {
        super.viewDidLoad()
        configureCollectionView()
        configureDataSource()
        updateSnapshot(animated: false)
    }

    private func configureCollectionView() {
        let layout = UICollectionViewFlowLayout()
        layout.scrollDirection = .horizontal
        layout.itemSize = CGSize(width: view.bounds.width, height: view.bounds.height)

        collectionView = UICollectionView(frame: view.bounds, collectionViewLayout: layout)
        collectionView.autoresizingMask = [.flexibleWidth, .flexibleHeight]
        collectionView.backgroundColor = .systemBackground
        collectionView.delegate = self
        collectionView.isPagingEnabled = true
        collectionView.showsHorizontalScrollIndicator = false

        view.addSubview(collectionView)
    }

    private func configureDataSource() {
        collectionView.register(DayCell.self, forCellWithReuseIdentifier: DayCell.reuseIdentifier)

        dataSource = UICollectionViewDiffableDataSource<Int, Date>(collectionView: collectionView) {
            (collectionView, indexPath, date) -> UICollectionViewCell? in

            let cell = collectionView.dequeueReusableCell(withReuseIdentifier: DayCell.reuseIdentifier, for: indexPath) as! DayCell
            cell.date = date
            return cell
        }
    }

    private func updateSnapshot(animated: Bool = true) {
        var snapshot = NSDiffableDataSourceSnapshot<Int, Date>()
        snapshot.appendSections([0])
        snapshot.appendItems([currentDay], toSection: 0)
        dataSource.apply(snapshot, animatingDifferences: animated)
    }

    // MARK: UICollectionViewDelegate

    func scrollViewDidEndDecelerating(_ scrollView: UIScrollView) {
        let offsetX = scrollView.contentOffset.x
        let width = scrollView.frame.width

        if offsetX > width {
            currentDay = Calendar.current.date(byAdding: .day, value: 1, to: currentDay)!
        } else if offsetX < width {
            currentDay = Calendar.current.date(byAdding: .day, value: -1, to: currentDay)!
        }
        updateSnapshot()
        collectionView.scrollToItem(at: IndexPath(item: 0, section: 0), at: .centeredHorizontally, animated: false)
    }
}

class DayCell: UICollectionViewCell {
    static let reuseIdentifier = "day-cell"

    private let dateLabel: UILabel = {
        let label = UILabel()
        label.translatesAutoresizingMaskIntoConstraints = false
        label.textAlignment = .center
        label.font = UIFont.systemFont(ofSize: 24, weight: .bold)
        return label
    }()

    var date: Date? {
        didSet {
            if let date = date {
                let formatter = DateFormatter()
                formatter.dateFormat = "EEEE, MMM d, yyyy"
